new='''  app.get("/orders", async (req, res) => {
    const PAGE_SIZE = 20;
    let before: number | null = null;
    if (req.query.cursor !== undefined) {
      const raw = req.query.cursor;
      const decoded = typeof raw === "string" ? Buffer.from(raw, "base64url").toString("utf8") : "";
      if (!/^[1-9]\\d{0,9}$/.test(decoded) || Number(decoded) > 2147483647) {
        return sendError(res, 400, "invalid_cursor", "Invalid cursor");
      }
      before = Number(decoded);
    }
    // Newest first. Ids are monotonic, so (user_id, id desc) gives a stable keyset order.
    const { rows } = await pool.query(
      `select id, status, total_cents, created_at from orders
       where user_id = $1 and ($2::int is null or id < $2)
       order by id desc limit $3`,
      [res.locals.user.id, before, PAGE_SIZE + 1],
    );
    const hasMore = rows.length > PAGE_SIZE;
    const orders = hasMore ? rows.slice(0, PAGE_SIZE) : rows;
    const nextCursor = hasMore ? Buffer.from(String(orders[orders.length - 1].id)).toString("base64url") : null;
    res.json({ orders, nextCursor });
  });

'''
