test("/orders paginates 20 per page with a cursor", async () => {
  await pool.query(
    "insert into orders (user_id, status, total_cents) select 2, 'paid', 100 from generate_series(1, 44)",
  );
  const seen: number[] = [];
  let cursor: string | null = null;
  let pages = 0;
  do {
    const url: string = `${base}/orders${cursor ? `?cursor=${cursor}` : ""}`;
    const body: { orders: { id: number }[]; nextCursor: string | null } = await (await fetch(url, { headers: as("bob-token") })).json();
    assert.ok(body.orders.length <= 20);
    seen.push(...body.orders.map((o) => o.id));
    cursor = body.nextCursor;
    pages++;
  } while (cursor);
  assert.equal(pages, 3);
  assert.equal(seen.length, 45);
  assert.equal(new Set(seen).size, 45);
  assert.deepEqual(seen, [...seen].sort((x, y) => y - x));
});

test("/orders rejects a bad cursor with 400", async () => {
  for (const c of ["abc", "!!", "LTE", ""]) {
    const res = await fetch(`${base}/orders?cursor=${c}`, { headers: as("alice-token") });
    assert.equal(res.status, 400);
    assert.equal((await res.json()).error.code, "invalid_cursor");
  }
});

